"""A small Sudoku game and solver."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Iterable

Board = list[list[int]]


@dataclass(frozen=True, slots=True)
class Sudoku:
    board: Board

    @classmethod
    def from_string(cls, puzzle: str) -> "Sudoku":
        """Create a Sudoku from an 81-character string.

        Digits 1-9 are fixed values; 0 or . mean empty cells.
        Whitespace is ignored.
        """
        chars = [c for c in puzzle if not c.isspace()]
        if len(chars) != 81:
            raise ValueError("puzzle must contain exactly 81 cells")

        board: Board = []
        for row in range(9):
            values: list[int] = []
            for col in range(9):
                c = chars[row * 9 + col]
                if c in {"0", "."}:
                    values.append(0)
                elif c.isdigit() and c != "0":
                    values.append(int(c))
                else:
                    raise ValueError(f"invalid cell value: {c!r}")
            board.append(values)
        sudoku = cls(board)
        sudoku._validate_board()
        return sudoku

    def render(self) -> str:
        """Render the board as a human-readable grid."""
        lines: list[str] = []
        for r, row in enumerate(self.board):
            if r in {3, 6}:
                lines.append("------+-------+------")
            parts = []
            for c, value in enumerate(row):
                if c in {3, 6}:
                    parts.append("|")
                parts.append(str(value) if value else ".")
            lines.append(" ".join(parts))
        return "\n".join(lines)

    def solve(self) -> bool:
        """Solve the puzzle in place. Returns True if solved."""
        empty = self._find_empty()
        if empty is None:
            return True
        row, col = empty
        for value in range(1, 10):
            if self._can_place(row, col, value):
                self.board[row][col] = value
                if self.solve():
                    return True
                self.board[row][col] = 0
        return False

    def _find_empty(self) -> tuple[int, int] | None:
        for r in range(9):
            for c in range(9):
                if self.board[r][c] == 0:
                    return r, c
        return None

    def _can_place(self, row: int, col: int, value: int) -> bool:
        if any(self.board[row][c] == value for c in range(9)):
            return False
        if any(self.board[r][col] == value for r in range(9)):
            return False
        box_row = (row // 3) * 3
        box_col = (col // 3) * 3
        for r in range(box_row, box_row + 3):
            for c in range(box_col, box_col + 3):
                if self.board[r][c] == value:
                    return False
        return True

    def _validate_board(self) -> None:
        for r in range(9):
            for c in range(9):
                value = self.board[r][c]
                if value and not self._can_place_value(r, c, value):
                    raise ValueError("invalid Sudoku puzzle")

    def _can_place_value(self, row: int, col: int, value: int) -> bool:
        for c in range(9):
            if c != col and self.board[row][c] == value:
                return False
        for r in range(9):
            if r != row and self.board[r][col] == value:
                return False
        box_row = (row // 3) * 3
        box_col = (col // 3) * 3
        for r in range(box_row, box_row + 3):
            for c in range(box_col, box_col + 3):
                if (r, c) != (row, col) and self.board[r][c] == value:
                    return False
        return True


def solve(puzzle: str) -> str:
    sudoku = Sudoku.from_string(puzzle)
    if not sudoku.solve():
        raise ValueError("puzzle has no solution")
    return "".join(str(cell) for row in sudoku.board for cell in row)

