"""A tiny crossword builder."""

from __future__ import annotations

from dataclasses import dataclass

EMPTY = "."
BLOCK = "#"


@dataclass(frozen=True, slots=True)
class Crossword:
    width: int
    height: int
    grid: list[list[str]]

    @classmethod
    def empty(cls, width: int, height: int) -> "Crossword":
        if width <= 0 or height <= 0:
            raise ValueError("crossword dimensions must be positive")
        return cls(width=width, height=height, grid=[[EMPTY for _ in range(width)] for _ in range(height)])

    def place(self, word: str, row: int, col: int, direction: str) -> None:
        if not word:
            raise ValueError("word must not be empty")
        if direction not in {"across", "down"}:
            raise ValueError("direction must be 'across' or 'down'")

        dr, dc = (0, 1) if direction == "across" else (1, 0)
        for i, ch in enumerate(word.upper()):
            r = row + dr * i
            c = col + dc * i
            if not (0 <= r < self.height and 0 <= c < self.width):
                raise ValueError("word does not fit in grid")
            existing = self.grid[r][c]
            if existing not in {EMPTY, ch}:
                raise ValueError("word conflicts with existing entry")

        for i, ch in enumerate(word.upper()):
            r = row + dr * i
            c = col + dc * i
            self.grid[r][c] = ch

    def block(self, row: int, col: int) -> None:
        self._check_bounds(row, col)
        self.grid[row][col] = BLOCK

    def render(self) -> str:
        return "\n".join("".join(row) for row in self.grid)

    def _check_bounds(self, row: int, col: int) -> None:
        if not (0 <= row < self.height and 0 <= col < self.width):
            raise ValueError("cell out of bounds")


def build(width: int, height: int, words: list[tuple[str, int, int, str]]) -> str:
    crossword = Crossword.empty(width, height)
    for word, row, col, direction in words:
        crossword.place(word, row, col, direction)
    return crossword.render()

"""A simple Scrabble game implementation."""

from dataclasses import dataclass
from collections import Counter

# Point values for letters in Scrabble
POINTS = {
    'A': 1, 'B': 3, 'C': 3, 'D': 2, 'E': 1,
    'F': 4, 'G': 2, 'H': 4, 'I': 1, 'J': 8,
    'K': 5, 'L': 1, 'M': 3, 'N': 1, 'O': 1,
    'P': 3, 'Q': 10, 'R': 1, 'S': 1, 'T': 1,
    'U': 1, 'V': 4, 'W': 4, 'X': 8, 'Y': 4, 'Z': 10
}


@dataclass
class Scrabble:
    tiles: Counter
    score: int = 0

    @classmethod
    def from_tiles(cls, tiles: list[str]) -> Scrabble:
        return cls(tiles=Counter(tiles))

    def play_word(self, word: str) -> int:
        word = word.upper()
        if not self._can_play(word):
            raise ValueError(f"Cannot play word: {word}")
        self.score += self._calculate_word_score(word)
        self._update_tiles(word)
        return self.score

    def _can_play(self, word: str) -> bool:
        word_count = Counter(word)
        return all(word_count[letter] <= self.tiles[letter] for letter in word_count)

    def _calculate_word_score(self, word: str) -> int:
        return sum(POINTS[letter] for letter in word)

    def _update_tiles(self, word: str) -> None:
        for letter in word:
            self.tiles[letter] -= 1


def build_tiles(available_tiles: list[str]) -> Scrabble:
    return Scrabble.from_tiles(available_tiles)

